<?php if (!defined('ABSPATH')) exit; $all_ids=array_unique(array_merge($up,$past)); $all=[]; foreach($all_ids as $eid)$all[]=$this->event_data($eid); $types=get_terms(['taxonomy'=>Tranter_Events::TYPE_TAX,'hide_empty'=>true]); $partners=get_terms(['taxonomy'=>Tranter_Events::PARTNER_TAX,'hide_empty'=>true]); $event_years=[]; foreach($all as $ev) $event_years[wp_date('Y',$ev['start'])]=true; ksort($event_years); ?>
