<section class="tranter-events-hero"><div class="tranter-hero-copy"><span class="tranter-eyebrow">TRANTER EVENTS</span><h1>Connecting Technology, People &amp; Possibilities.</h1><p>From industry conferences and technology showcases to partner events and knowledge-sharing sessions, Tranter connects businesses with the technology and experts shaping the future.</p><a class="tranter-button" href="#tranter-upcoming">Explore Events</a></div><?php if($next): ?><div class="tranter-featured"><span class="tranter-eyebrow">NEXT UP</span><?php if($next['image']): ?><img src="<?php echo esc_url($next['image']); ?>" alt="<?php echo esc_attr($next['title']); ?>"><?php endif; ?><div class="tranter-featured-body"><strong><?php echo esc_html($next['date']); ?></strong><h2><?php echo esc_html($next['title']); ?></h2><p><?php echo esc_html($next['location']); ?></p><div class="tranter-countdown" data-target="<?php echo esc_attr($next['start']); ?>"><b data-unit="days">0</b><span>Days</span><b data-unit="hours">0</b><span>Hours</span><b data-unit="minutes">0</b><span>Minutes</span><b data-unit="seconds">0</b><span>Seconds</span></div></div></div><?php endif; ?></section>
