<?php if($a['show_filters']==='true'): ?><form class="tranter-filters" data-events-filter><label>Event status<select name="status"><option value="all">All Events</option><option value="upcoming" selected>Upcoming</option><option value="past">Past</option></select></label><label>Event type<select name="event_type"><option value="">All types</option><?php foreach($types as $t): ?><option value="<?php echo esc_attr($t->slug); ?>"><?php echo esc_html($t->name); ?></option><?php endforeach; ?></select></label><label>Partner<select name="partner"><option value="">All partners</option><?php foreach($partners as $t): ?><option value="<?php echo esc_attr($t->slug); ?>"><?php echo esc_html($t->name); ?></option><?php endforeach; ?></select></label><label>Year<select name="year"><option value="">All years</option><?php foreach(array_keys($event_years) as $y): ?><option value="<?php echo esc_attr($y); ?>"><?php echo esc_html($y); ?></option><?php endforeach; ?></select></label></form><?php endif; ?><div class="tranter-event-grid" data-events-results><?php if($up): foreach($up as $id) tranter_events_render_card($this->event_data($id)); else: ?><div class="tranter-empty"><h3>No Upcoming Events</h3><p>There are currently no upcoming events. Check back soon for what’s next.</p></div><?php endif; ?></div></section>
<section class="tranter-event-section tranter-past"><div class="tranter-section-heading"><div><span class="tranter-eyebrow">EVENT ARCHIVE</span><h2>Where We’ve Been</h2><p>Explore events, conferences and partner experiences from across Tranter’s journey.</p></div></div><div class="tranter-event-grid tranter-past-grid"><?php if($past): foreach($past as $id) tranter_events_render_card($this->event_data($id)); else: ?><div class="tranter-empty"><h3>No Past Events</h3><p>Our event history will appear here.</p></div><?php endif; ?></div></section>
<?php if($a['show_gallery']==='true'): ?><section class="tranter-event-section"><div class="tranter-section-heading"><div><span class="tranter-eyebrow">EVENT PHOTOS</span><h2>Moments That Matter</h2><p>Photos from Tranter’s events and partner experiences.</p></div></div><div class="tranter-gallery"><?php $found=false; foreach($all as $ev) foreach($ev['gallery'] as $img){$found=true; ?><button type="button" data-lightbox="<?php echo esc_url($img); ?>"><img src="<?php echo esc_url($img); ?>" alt="Event photo"></button><?php } if(!$found): ?><div class="tranter-empty"><h3>No Event Photos Yet</h3><p>Photos from our events will appear here.</p></div><?php endif; ?></div></section><?php endif; ?>
